{"nbformat":4,"nbformat_minor":0,"metadata":{"colab":{"provenance":[],"authorship_tag":"ABX9TyNaXET5OsjOlWhtxN14Vmg1"},"kernelspec":{"name":"python3","display_name":"Python 3"},"language_info":{"name":"python"}},"cells":[{"cell_type":"code","execution_count":null,"metadata":{"id":"solYH03Jnx8k"},"outputs":[],"source":["%%writefile /content/drive/MyDrive/UNet-LIDC-Segmentation/src/metrics.py\n","import tensorflow as tf\n","from tensorflow.keras import backend as K\n","\n","\n","def dice_coefficient(y_true, y_pred, smooth=1e-6):\n","    y_true_f = K.flatten(y_true)\n","    y_pred_f = K.flatten(y_pred)\n","    intersection = K.sum(y_true_f * y_pred_f)\n","    return (2.0 * intersection + smooth) / (\n","        K.sum(y_true_f) + K.sum(y_pred_f) + smooth\n","    )\n","\n","\n","def dice_loss(y_true, y_pred):\n","    return 1.0 - dice_coefficient(y_true, y_pred)\n","\n","\n","def binary_iou(y_true, y_pred, smooth=1e-6):\n","    y_true_f = K.flatten(y_true)\n","    y_pred_f = K.cast(K.flatten(y_pred) > 0.5, \"float32\")\n","    intersection = K.sum(y_true_f * y_pred_f)\n","    union = K.sum(y_true_f) + K.sum(y_pred_f) - intersection\n","    return (intersection + smooth) / (union + smooth)\n"]}]}